+}
+
+.example__trigger:focus-visible {
+  outline: 2px solid var(--color-primary);
+  outline-offset: -2px;
+  border-radius: var(--radius-card);
+}
+
+/* ── Chevron icon ───────────────────────────────────────── */
+.example__icon {
+  flex-shrink: 0;
+  width: 1.25rem;
+  height: 1.25rem;
+  color: var(--color-text-muted);
+  transition: transform var(--transition), color var(--transition);
+}
+
+.example__trigger[aria-expanded="true"] .example__icon {
+  transform: rotate(180deg);
+  color: var(--color-primary);
+}
+
+/* ── Answer panel ───────────────────────────────────────── */
+.details {
+  overflow: hidden;
+  display: grid;
+  grid-template-rows: 0fr;
+  transition: grid-template-rows var(--transition);
+}
+
+.details[data-open="true"] {
+  grid-template-rows: 1fr;
+}
+
+.details__inner {
+  overflow: hidden;
+}
+
+.details__body {
+  border-top: 1px solid var(--color-border);
+  background: var(--color-answer-bg);
+  padding: 1rem 1.4rem 1.25rem;
+  color: var(--color-text-muted);
+  font-size: 0.97rem;
+  line-height: 1.7;
+}
+
+.details__body p + p {
+  margin-top: 0.75rem;
+}
+
+/* ── Footer ─────────────────────────────────────────────── */
+footer {
+  text-align: center;
+  margin-top: 3rem;
+  color: var(--color-text-muted);
+  font-size: 0.85rem;
+}
+
+/* ── Reflow at 320 px ───────────────────────────────────── */
+@media (max-width: 400px) {
+  .example__trigger {
+    padding: 0.9rem 1rem;
+  }
+  .details__body {
+    padding: 0.9rem 1rem 1rem;
+  }
+}
+
+/* ── Reduced motion ─────────────────────────────────────── */
+@media (prefers-reduced-motion: reduce) {
+  .details,
+  .example__icon {
+    transition: none;
+  }
+}
+
+/* ── Forced colors ──────────────────────────────────────── */
+@media (forced-colors: active) {
+  .example {
+    border: 2px solid ButtonBorder;
+  }
+  .example__trigger:focus-visible {
+    outline: 2px solid Highlight;
+  }
+  .example__icon {
+    fill: ButtonText;
+    stroke: ButtonText;
+  }
+}
